head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF00001";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf00001.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_chgPw_onclick
 * @description btn_chgPw 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_chgPw_onclick = async function(e){
    try {
        await scwin.chgPw()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00001.btn_chgPw_onclick' }); }
};

/**
 * @method
 * @name btn_delayPwChgEndDd_onclick
 * @description btn_delayPwChgEndDd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delayPwChgEndDd_onclick = async function(e){
    try {
        await scwin.delayPwChgEndDd()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00001.btn_delayPwChgEndDd_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_chgPw
 * @description chg Pw 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_chgPw = async function () {
    const sbmOptions = {
        id: "tx_fn_chgPw",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_chgPwReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delayPwChgEndDd
 * @description delay Pw Chg End Dd 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delayPwChgEndDd = async function () {
    const sbmOptions = {
        id: "tx_fn_delayPwChgEndDd",
        method: "post",
        action: "/account/userPw.do",
        ref: "dma_delayPwChgEndDdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name chgPw
 * @description chg Pw 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chgPw = async function () {
    await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /account/userPw.do?method=updatePasswordMain&deal_div=1). 전환 대상 화면이 확정되면 연결됩니다.');
};

/**
 * @method
 * @name delayPwChgEndDd
 * @description delay Pw Chg End Dd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delayPwChgEndDd = async function () {
    $c.util.getComponent("dma_chgPwReq").set("method", "delayPwChgEndDd");
    await scwin.tx_fn_delayPwChgEndDd();
};
